/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventTablePackageClassId extends UPSPricingAttributeWHSInventTable implements UPSIPricingAttribute
{
}

