public str getName()
{
    return fieldPName(WHSInventTable, PackageClassId);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::String);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by PackageClassId
    {
        if (! ret.in(wHSInventTable.PackageClassId))
        {
            ret.add(wHSInventTable.PackageClassId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, PackageClassId));
    qbr.value(queryValue(_value));
}
